#!/usr/bin/env bash
# B-25H cockpit pass 2 (v3) art: every call through fal (um fal), manifest in this folder (merged into assets/fal_manifest.jsonl)
O="$(cd "$(dirname "$0")" && pwd)"
cd "$O"
um fal edit "Turn this layout guide into a photoreal flat straight-on game texture of the main instrument panel of a WWII North American B-25 Mitchell bomber, restored, with three small modern retrofit avionics units. KEEP THE LAYOUT EXACTLY: same canvas, the same ARCHED panel outline (curved top edge, everything outside the outline stays pure white); every BLACK circle stays an empty pure black hole with a thin dark metal bezel ring (real instruments are fitted there later); every LIGHT GREY circle becomes a 1940s round aircraft instrument with a black face, white numerals and a needle, each a different instrument (clock, suction, ammeter, carburettor air temperature, free air temperature, oxygen, compass, de-icer pressure); every black RECTANGLE stays an empty pure black opening with a thin dark frame; the small orange and red dots become small round red and amber warning-light jewels; the light marks along the bottom become a row of 1940s black bat-handle toggle switches with tiny white stencilled labels. Panel: worn black crinkle paint, small white stencilled labels under the instruments, screws in the corners, a few small data placards, faint scuffs. Dense, busy, period-correct. No perspective, no extra objects, even flat lighting." --ref panel_layout_guide_v3.png --aspect 21:9 --res 2K --n 2 --seed 7301 --out "$O" --name panel_main_v3 > log_panel.txt 2>&1 &
um fal image "Flat orthographic straight-on game texture filling the whole frame, very wide strip: the lower switch panel under the instrument panel of a WWII B-25 Mitchell bomber, pilot side, black crinkle painted metal panel with rows of 1940s black bat-handle toggle switches, two rotary selector knobs, small red guarded switch, white stencilled labels (IGNITION, LANDING LIGHTS, PITOT HEAT, FUEL BOOSTER, PROP FEATHER), small data placards, screws along the edges, worn paint. No perspective, no shadow, even flat lighting, no background." --aspect 21:9 --res 2K --seed 7302 --out "$O" --name lower_left > log_lower_left.txt 2>&1 &
um fal image "Flat orthographic straight-on game texture filling the whole frame, very wide strip: the lower switch panel under the instrument panel of a WWII B-25 Mitchell bomber, right side, black crinkle painted metal panel with rows of 1940s black toggle switches, a bomb-bay door selector, a small round dial, white stencilled labels (BOMB DOORS, GUN HEAT, INVERTER, RADIO MASTER, DE-ICER), small data placards, screws along the edges, worn paint. No perspective, no shadow, even flat lighting, no background." --aspect 21:9 --res 2K --seed 7303 --out "$O" --name lower_right > log_lower_right.txt 2>&1 &
um fal image "Flat orthographic straight-on game texture filling the whole frame: a WWII B-25 bomber cockpit left side wall equipment panel, olive drab painted metal box face with an oxygen regulator gauge, an interphone jack box with a rotary selector, a row of small circuit breakers, a black placard with white text, screws at the corners, worn paint and scuffs. No perspective, no shadow, even flat lighting, no background." --aspect 4:3 --res 2K --seed 7304 --out "$O" --name box_left2 > log_box_left2.txt 2>&1 &
um fal texture "WWII bomber cockpit sidewall soundproofing blanket, dark olive drab khaki canvas, quilted with stitched diamond pattern, small diamonds about one tenth of the tile, slightly puffy cells, worn, dirty, darker toward the seams, flat top-down orthographic, even lighting, seamless tileable texture" --tiling both --out "$O" --name quilt_od_v3 > log_quilt.txt 2>&1 &
for n in boot footrest loom; do :; done
um fal image "Isolated product render on a plain white background, 3/4 view: the black leather and canvas dust boot (gaiter) at the base of a WWII B-25 bomber control column, a conical pleated boot about 30 cm wide at the bottom narrowing up to a tube collar, clamped to a square floor plate with screws, worn. Single object, centred, full object visible, soft studio light, no text." --aspect 1:1 --res 1K --seed 7311 --out "$O" --name concept_boot > log_c_boot.txt 2>&1 &
um fal image "Isolated product render on a plain white background, 3/4 view: a WWII aircraft navigator's footrest, an olive drab painted steel tube frame bolted to a floor bracket with a slanted ribbed anti-slip foot plate on top, about 40 cm wide. Single object, centred, full object visible, soft studio light, no text." --aspect 1:1 --res 1K --seed 7312 --out "$O" --name concept_footrest > log_c_footrest.txt 2>&1 &
um fal image "Isolated product render on a plain white background, side view: a straight 60 cm long WWII aircraft cockpit wiring loom, a bundle of cloth-covered black and khaki electrical wires laced together with waxed cord, held by three olive drab metal P-clamps with mounting tabs, a couple of wires branching off. Single object, horizontal, centred, full object visible, soft studio light, no text." --aspect 16:9 --res 1K --seed 7313 --out "$O" --name concept_loom > log_c_loom.txt 2>&1 &
wait
echo ALL_DONE
